import sys, json, re
from collections import Counter
from pathlib import Path
from graphify.build import build_from_json
from graphify.cluster import score_all
from graphify.analyze import suggest_questions
from graphify.report import generate

extraction = json.loads(Path('graphify-out/.graphify_extract.json').read_text(encoding='utf-8'))
detection  = json.loads(Path('graphify-out/.graphify_detect.json').read_text(encoding='utf-8'))
analysis   = json.loads(Path('graphify-out/.graphify_analysis.json').read_text(encoding='utf-8'))

G = build_from_json(extraction)
communities = {int(k): v for k, v in analysis['communities'].items()}
cohesion = {int(k): v for k, v in analysis['cohesion'].items()}
tokens = {'input': extraction.get('input_tokens', 0), 'output': extraction.get('output_tokens', 0)}
node_data = {n: G.nodes[n] for n in G.nodes}
stop = set('src lib app components component ts tsx js jsx json index types type props data item items use set get handle create update delete page tab form ui class function const default export import from voicebox'.split())

def split_words(s):
    parts = re.findall(r'[A-Z]+(?=[A-Z][a-z])|[A-Z]?[a-z]+|[0-9]+', s or '')
    if not parts:
        parts = re.findall(r'[a-z0-9]+', (s or '').lower())
    return [p.lower() for p in parts]

def title_from_words(words):
    nice=[]
    for w,_ in words:
        if w in {'api','mcp','tts','ui','gpu','sse'}:
            nice.append(w.upper())
        elif w == 'i18n':
            nice.append('I18n')
        else:
            nice.append(w.capitalize())
        if len(nice) >= 4:
            break
    return ' '.join(nice) if nice else 'Misc Components'

labels={}
for cid, nodes in communities.items():
    c=Counter()
    for nid in nodes:
        d=node_data.get(nid, {})
        label=d.get('label') or nid
        src=d.get('source_file') or ''
        for w in split_words(label):
            if len(w) >= 3 and w not in stop:
                c[w]+=3
        for comp in re.split(r'[/_.-]+', src):
            for w in split_words(comp):
                if len(w) >= 3 and w not in stop:
                    c[w]+=1
    labels[cid]=title_from_words(c.most_common(8))

questions = suggest_questions(G, communities, labels)
report = generate(G, communities, cohesion, labels, analysis['gods'], analysis['surprises'], detection, tokens, '.', suggested_questions=questions)
Path('graphify-out/GRAPH_REPORT.md').write_text(report, encoding='utf-8')
Path('graphify-out/.graphify_labels.json').write_text(json.dumps({str(k): v for k, v in labels.items()}, ensure_ascii=False), encoding='utf-8')
print('Report updated with community labels')
print(f'Labeled {len(labels)} communities')
"

