15	/**
16	 * Engine/model options and their display metadata.
17	 * Adding a new engine means adding one entry here.
18	 */
19	const ENGINE_OPTIONS = [
20	  { value: 'qwen:1.7B', label: 'Qwen3-TTS 1.7B', engine: 'qwen' },
21	  { value: 'qwen:0.6B', label: 'Qwen3-TTS 0.6B', engine: 'qwen' },
