28	  { value: 'tada:3B', label: 'TADA 3B Multilingual', engine: 'tada' },
29	  { value: 'kokoro', label: 'Kokoro 82M', engine: 'kokoro' },
30	] as const;
31	
32	const ENGINE_DESCRIPTIONS: Record<string, string> = {
33	  qwen: 'Multi-language, two sizes',
34	  qwen_custom_voice: '9 preset voices, instruct control',
35	  luxtts: 'Fast, English-focused',
36	  chatterbox: '23 languages, incl. Hebrew',
37	  chatterbox_turbo: 'English, [laugh] [cough] tags',
38	  tada: 'HumeAI, 700s+ coherent audio',
39	  kokoro: '82M params, CPU realtime, 8 langs',
