42	/** Engines that only support English and should force language to 'en' on select. */
43	const ENGLISH_ONLY_ENGINES = new Set(['luxtts', 'chatterbox_turbo']);
44	
45	/** Engines that support cloned (reference audio) profiles. */
46	const CLONING_ENGINES = new Set(['qwen', 'luxtts', 'chatterbox', 'chatterbox_turbo', 'tada']);
47	
48	function getAvailableOptions(selectedProfile?: VoiceProfileResponse | null) {
49	  if (!selectedProfile) return ENGINE_OPTIONS;
50	  return ENGINE_OPTIONS.filter((opt) => isProfileCompatibleWithEngine(selectedProfile, opt.engine));
51	}
