53	function getSelectValue(engine: string, modelSize?: string): string {
54	  if (engine === 'qwen') return `qwen:${modelSize || '1.7B'}`;
55	  if (engine === 'qwen_custom_voice') return `qwen_custom_voice:${modelSize || '1.7B'}`;
56	  if (engine === 'tada') return `tada:${modelSize || '1B'}`;
57	  return engine;
58	}
59	
60	export function applyEngineSelection(form: UseFormReturn<GenerationFormValues>, value: string) {
61	  if (value.startsWith('qwen_custom_voice:')) {
62	    const [, modelSize] = value.split(':');
63	    form.setValue('engine', 'qwen_custom_voice');
64	    form.setValue('modelSize', modelSize as '1.7B' | '0.6B');
65	    const currentLang = form.getValues('language');
66	    const available = getLanguageOptionsForEngine('qwen_custom_voice');
67	    if (!available.some((l) => l.value === currentLang)) {
68	      form.setValue('language', available[0]?.value ?? 'en');
69	    }
70	  } else if (value.startsWith('qwen:')) {
71	    const [, modelSize] = value.split(':');
72	    form.setValue('engine', 'qwen');
73	    form.setValue('modelSize', modelSize as '1.7B' | '0.6B');
74	    // Validate language is supported by Qwen
75	    const currentLang = form.getValues('language');
76	    const available = getLanguageOptionsForEngine('qwen');
77	    if (!available.some((l) => l.value === currentLang)) {
78	      form.setValue('language', available[0]?.value ?? 'en');
79	    }
80	  } else if (value.startsWith('tada:')) {
81	    const [, modelSize] = value.split(':');
82	    form.setValue('engine', 'tada');
83	    form.setValue('modelSize', modelSize as '1B' | '3B');
84	    // TADA 1B is English-only; 3B is multilingual
85	    if (modelSize === '1B') {
86	      form.setValue('language', 'en');
87	    } else {
88	      const currentLang = form.getValues('language');
89	      const available = getLanguageOptionsForEngine('tada');
90	      if (!available.some((l) => l.value === currentLang)) {
91	        form.setValue('language', available[0]?.value ?? 'en');
92	      }
93	    }
94	  } else {
95	    form.setValue('engine', value as GenerationFormValues['engine']);
96	    form.setValue('modelSize', undefined as unknown as '1.7B' | '0.6B');
97	    if (ENGLISH_ONLY_ENGINES.has(value)) {
98	      form.setValue('language', 'en');
99	    } else {
100	      // If current language isn't supported by the new engine, reset to first available
101	      const currentLang = form.getValues('language');
102	      const available = getLanguageOptionsForEngine(value);
103	      if (!available.some((l) => l.value === currentLang)) {
104	        form.setValue('language', available[0]?.value ?? 'en');
105	      }
106	    }
107	  }
108	}
109	
110	interface EngineModelSelectorProps {
111	  form: UseFormReturn<GenerationFormValues>;
112	  compact?: boolean;
113	  selectedProfile?: VoiceProfileResponse | null;
114	}
115	
116	export function EngineModelSelector({ form, compact, selectedProfile }: EngineModelSelectorProps) {
117	  const engine = form.watch('engine') || 'qwen';
118	  const modelSize = form.watch('modelSize');
119	  const selectValue = getSelectValue(engine, modelSize);
120	  const availableOptions = getAvailableOptions(selectedProfile);
121	
122	  const currentEngineAvailable = availableOptions.some((opt) => opt.value === selectValue);
123	
124	  useEffect(() => {
125	    if (!currentEngineAvailable && availableOptions.length > 0) {
126	      applyEngineSelection(form, availableOptions[0].value);
127	    }
128	  }, [availableOptions, currentEngineAvailable, form]);
129	
130	  const itemClass = compact ? 'text-xs text-muted-foreground' : undefined;
131	  const triggerClass = compact
132	    ? 'h-8 text-xs bg-card border-border rounded-full hover:bg-background/50 transition-all'
133	    : undefined;
