55	function formatErrorDetail(detail: unknown, fallback: string): string {
56	  if (typeof detail === 'string') return detail;
57	  if (Array.isArray(detail)) {
58	    return detail
59	      .map((e: Record<string, unknown>) => e.msg || e.message || JSON.stringify(e))
60	      .join('; ');
61	  }
62	  if (detail && typeof detail === 'object') {
63	    const obj = detail as Record<string, unknown>;
64	    if (typeof obj.message === 'string') return obj.message;
65	    return JSON.stringify(detail);
66	  }
67	  return fallback;
68	}
69	
70	class ApiClient {
71	  private getBaseUrl(): string {
72	    const serverUrl = useServerStore.getState().serverUrl;
73	    return serverUrl;
74	  }
75	
76	  private async request<T>(endpoint: string, options?: RequestInit): Promise<T> {
77	    const url = `${this.getBaseUrl()}${endpoint}`;
78	    const response = await fetch(url, {
79	      ...options,
80	      headers: {
81	        'Content-Type': 'application/json',
82	        ...options?.headers,
83	      },
84	    });
85	
86	    if (!response.ok) {
87	      const error = await response.json().catch(() => ({
88	        detail: response.statusText,
89	      }));
90	      throw new Error(formatErrorDetail(error.detail, `HTTP error! status: ${response.status}`));
91	    }
92	
93	    return response.json();
94	  }
95	
96	  // Health
97	  async getHealth(): Promise<HealthResponse> {
98	    return this.request<HealthResponse>('/health');
99	  }
100	
101	  // Profiles
102	  async createProfile(data: VoiceProfileCreate): Promise<VoiceProfileResponse> {
103	    return this.request<VoiceProfileResponse>('/profiles', {
104	      method: 'POST',
105	      body: JSON.stringify(data),
106	    });
107	  }
108	
109	  async listProfiles(): Promise<VoiceProfileResponse[]> {
110	    return this.request<VoiceProfileResponse[]>('/profiles');
111	  }
112	
113	  async getProfile(profileId: string): Promise<VoiceProfileResponse> {
114	    return this.request<VoiceProfileResponse>(`/profiles/${profileId}`);
115	  }
116	
117	  async listPresetVoices(engine: string): Promise<{ engine: string; voices: PresetVoice[] }> {
118	    return this.request<{ engine: string; voices: PresetVoice[] }>(`/profiles/presets/${engine}`);
119	  }
120	
121	  async updateProfile(profileId: string, data: VoiceProfileCreate): Promise<VoiceProfileResponse> {
122	    return this.request<VoiceProfileResponse>(`/profiles/${profileId}`, {
123	      method: 'PUT',
124	      body: JSON.stringify(data),
125	    });
126	  }
127	
128	  async deleteProfile(profileId: string): Promise<void> {
129	    await this.request<void>(`/profiles/${profileId}`, {
130	      method: 'DELETE',
131	    });
132	  }
133	
134	  // ── Personality-driven text generation ─────────────────────────────
135	  // Compose produces a fresh in-character utterance the UI drops into
136	  // the generate textarea. Rewrite now happens server-side inside
137	  // `/generate` when `personality: true` is passed in the request body.
138	
139	  async composeWithPersonality(profileId: string): Promise<PersonalityTextResponse> {
140	    return this.request<PersonalityTextResponse>(`/profiles/${profileId}/compose`, {
141	      method: 'POST',
142	    });
143	  }
144	
145	  async addProfileSample(
146	    profileId: string,
147	    file: File,
148	    referenceText: string,
149	  ): Promise<ProfileSampleResponse> {
150	    const url = `${this.getBaseUrl()}/profiles/${profileId}/samples`;
151	    const formData = new FormData();
152	    formData.append('file', file);
153	    formData.append('reference_text', referenceText);
154	
155	    const response = await fetch(url, {
156	      method: 'POST',
157	      body: formData,
158	    });
159	
160	    if (!response.ok) {
161	      const error = await response.json().catch(() => ({
