6	function resolveTheme(theme: Theme): 'light' | 'dark' {
7	  if (theme !== 'system') return theme;
8	  if (typeof window === 'undefined') return 'dark';
9	  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
10	}
11	
12	function applyTheme(theme: Theme) {
13	  if (typeof document === 'undefined') return;
14	  document.documentElement.classList.toggle('dark', resolveTheme(theme) === 'dark');
15	}
