122	/// Find a voicebox-server process listening on a given port (Windows only).
123	///
124	/// Uses PowerShell `Get-NetTCPConnection` to look up the PID owning the port,
125	/// then verifies via `tasklist` that it's a voicebox process. The caller is
126	/// responsible for checking port occupancy first (e.g. `TcpStream::connect_timeout`).
127	/// Replaces the previous `netstat -ano` approach which failed on systems with
128	/// corrupted system DLLs (see #277).
129	#[cfg(windows)]
130	fn find_voicebox_pid_on_port(port: u16) -> Option<u32> {
131	    use std::process::Command;
132	
133	    // Use PowerShell's Get-NetTCPConnection to find the PID listening on the port.
134	    // This is a built-in cmdlet that doesn't depend on netstat.exe.
135	    let ps_script = format!(
136	        "Get-NetTCPConnection -LocalPort {} -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess",
137	        port
138	    );
139	    if let Ok(output) = Command::new("powershell")
140	        .args(["-NoProfile", "-Command", &ps_script])
141	        .output()
142	    {
143	        let output_str = String::from_utf8_lossy(&output.stdout);
144	        for line in output_str.lines() {
145	            if let Ok(pid) = line.trim().parse::<u32>() {
146	                // Verify this PID is a voicebox process
147	                if let Ok(tasklist_output) = Command::new("tasklist")
148	                    .args(["/FI", &format!("PID eq {}", pid), "/FO", "CSV", "/NH"])
149	                    .output()
150	                {
151	                    let tasklist_str = String::from_utf8_lossy(&tasklist_output.stdout);
152	                    if tasklist_str.to_lowercase().contains("voicebox") {
153	                        return Some(pid);
154	                    }
155	                }
156	            }
157	        }
158	    }
159	
160	    None
161	}
