163	/// Check if a Voicebox server is responding on the given port.
164	///
165	/// Sends an HTTP GET to `/health` and returns `true` only if the response
166	/// is valid JSON matching the Voicebox `HealthResponse` schema — specifically
167	/// `status` must be `"healthy"`, and both `model_loaded` and `gpu_available`
168	/// must be present as booleans. This prevents misidentifying an unrelated
169	/// service that happens to expose a `/health` endpoint.
170	#[allow(dead_code)] // Used in platform-specific cfg blocks
171	fn check_health(port: u16) -> bool {
172	    let url = format!("http://127.0.0.1:{}/health", port);
173	    match reqwest::blocking::Client::builder()
174	        .timeout(std::time::Duration::from_secs(3))
175	        .build()
176	    {
177	        Ok(client) => match client.get(&url).send() {
178	            Ok(resp) => {
179	                if !resp.status().is_success() {
180	                    return false;
181	                }
182	                // Parse as JSON and validate Voicebox-specific fields
183	                match resp.json::<serde_json::Value>() {
184	                    Ok(body) => {
185	                        body.get("status").and_then(|v| v.as_str()) == Some("healthy")
186	                            && body.get("model_loaded").map(|v| v.is_boolean()).unwrap_or(false)
187	                            && body.get("gpu_available").map(|v| v.is_boolean()).unwrap_or(false)
188	                    }
189	                    Err(_) => false,
190	                }
191	            }
192	            Err(_) => false,
193	        },
194	        Err(_) => false,
195	    }
196	}
