198	struct ServerState {
199	    child: Mutex<Option<tauri_plugin_shell::process::CommandChild>>,
200	    server_pid: Mutex<Option<u32>>,
201	    keep_running_on_close: Mutex<bool>,
202	    models_dir: Mutex<Option<String>>,
203	}
204	
205	#[command]
206	async fn start_server(
207	    app: tauri::AppHandle,
208	    state: State<'_, ServerState>,
209	    remote: Option<bool>,
210	    models_dir: Option<String>,
211	) -> Result<String, String> {
212	    // Store models_dir for use on restart (empty string means reset to default)
213	    if let Some(ref dir) = models_dir {
214	        if dir.is_empty() {
215	            *state.models_dir.lock().unwrap() = None;
216	        } else {
217	            *state.models_dir.lock().unwrap() = Some(dir.clone());
218	        }
219	    }
220	    // Check if server is already running (managed by this app instance)
221	    if state.child.lock().unwrap().is_some() {
222	        return Ok(format!("http://127.0.0.1:{}", SERVER_PORT));
223	    }
224	
225	    // Check if a voicebox server is already running on our port (from previous session with keep_running=true,
226	    // or an externally started server e.g. via `python`, `uvicorn`, Docker, etc.)
227	    #[cfg(unix)]
228	    {
229	        use std::process::Command;
230	        if let Ok(output) = Command::new("lsof")
231	            .args(["-i", &format!(":{}", SERVER_PORT), "-sTCP:LISTEN"])
232	            .output()
233	        {
234	            let output_str = String::from_utf8_lossy(&output.stdout);
235	            for line in output_str.lines().skip(1) {
236	                let parts: Vec<&str> = line.split_whitespace().collect();
237	                if parts.len() >= 2 {
238	                    let command = parts[0];
239	                    let pid_str = parts[1];
240	                    if command.contains("voicebox") {
241	                        if let Ok(pid) = pid_str.parse::<u32>() {
242	                            println!("Found existing voicebox-server on port {} (PID: {}), reusing it", SERVER_PORT, pid);
243	                            // Store the PID so we can kill it on exit if needed
244	                            *state.server_pid.lock().unwrap() = Some(pid);
245	                            return Ok(format!("http://127.0.0.1:{}", SERVER_PORT));
246	                        }
247	                    } else {
248	                        // Process name doesn't contain "voicebox" — could be an external
249	                        // Python/uvicorn/Docker server. Verify via HTTP health check.
250	                        println!("Port {} in use by '{}' (PID: {}), checking if it's a Voicebox server...", SERVER_PORT, command, pid_str);
251	                        if check_health(SERVER_PORT) {
252	                            println!("Health check passed — reusing external server on port {}", SERVER_PORT);
253	                            return Ok(format!("http://127.0.0.1:{}", SERVER_PORT));
254	                        }
255	                        println!("Health check failed — port is occupied by a non-Voicebox process");
256	                        return Err(format!(
257	                            "Port {} is already in use by another application ({}). \
258	                             Close it or change the Voicebox server port.",
259	                            SERVER_PORT, command
260	                        ));
261	                    }
262	                }
263	            }
264	        }
265	    }
266	    
267	    #[cfg(windows)]
268	    {
269	        use std::net::TcpStream;
270	        if TcpStream::connect_timeout(
271	            &format!("127.0.0.1:{}", SERVER_PORT).parse().unwrap(),
272	            std::time::Duration::from_secs(1),
273	        ).is_ok() {
274	            // Port is in use — check if it's a voicebox process by name first
275	            if let Some(pid) = find_voicebox_pid_on_port(SERVER_PORT) {
276	                println!("Found existing voicebox-server on port {} (PID: {}), reusing it", SERVER_PORT, pid);
277	                *state.server_pid.lock().unwrap() = Some(pid);
278	                return Ok(format!("http://127.0.0.1:{}", SERVER_PORT));
279	            }
280	            // Process name doesn't match — could be an external Python/Docker server.
281	            // Verify via HTTP health check before giving up.
282	            println!("Port {} in use by unknown process, checking if it's a Voicebox server...", SERVER_PORT);
283	            if check_health(SERVER_PORT) {
284	                println!("Health check passed — reusing external server on port {}", SERVER_PORT);
285	                return Ok(format!("http://127.0.0.1:{}", SERVER_PORT));
286	            }
287	            return Err(format!(
288	                "Port {} is already in use by another application. \
289	                 Close the other application or change the Voicebox port.",
290	                SERVER_PORT
291	            ));
292	        }
293	    }
